<!DOCTYPE html><html lang="sr"><head><meta charset="utf-8"><title>Račun {{ $invoice->invoice_number }}</title><style>@page{margin:0}*{box-sizing:border-box}body{margin:0;background:#07111d;color:#d9f4ff;font-family:DejaVu Sans Mono,monospace;font-size:7.5pt}.p{padding:12mm 14mm 17mm}.top{padding:7mm 8mm;border:1px solid #16405b;background:#0c1b2b}.cyan{color:#22d3ee}.title{margin:4px 0;font-size:19pt;font-weight:bold}.right{text-align:right}.grid,.items,.sum{width:100%;border-collapse:collapse}.grid{margin:6mm 0}.grid>tbody>tr>td{width:50%;padding:6px 8px;vertical-align:top;border:1px solid #16405b}.grid>tbody>tr>td+td{border-left:0}.name{margin:4px 0;color:#fff;font-size:10pt;font-weight:bold}.muted{color:#82a6b8;line-height:1.45}.items th{padding:6px 4px;background:#123049;color:#22d3ee;font-size:6pt;text-align:left}.items td{padding:7px 4px;border-bottom:1px solid #13354c;vertical-align:top}.r{text-align:right;white-space:nowrap}.ct{text-align:center}.sum{width:43%;margin:7mm 0 0 auto;border:1px solid #16405b}.sum td{padding:6px;border-top:1px solid #16405b}.sum td:last-child{text-align:right;font-weight:bold}.total td{background:#22d3ee;color:#07111d;font-size:11pt}.box{margin-top:7mm;padding:7px 9px;border-left:3px solid #22d3ee;background:#0c1b2b;white-space:pre-line}.foot{position:fixed;right:14mm;bottom:7mm;left:14mm;color:#547a8c;font-size:6pt}</style></head><body><div class="p"><div class="top"><table class="grid"><tr><td style="border:0"><div class="cyan">OPS::RAČUN / IZDAN</div><div class="title">{{ $company->name }}</div><div class="muted">{{ $company->address }}<br>{{ $company->zip }} {{ $company->city }}@if($company->identification_number)<br>JIB: {{ $company->identification_number }}@endif</div></td><td class="right" style="border:0"><div class="cyan">IDENTIFIKATOR</div><div class="title">{{ $invoice->invoice_number }}</div><div class="muted">{{ $invoice->date?->format('d.m.Y.') }}</div></td></tr></table></div><table class="grid"><tr><td><div class="cyan">KUPAC</div><div class="name">{{ $invoice->client?->name ?? '—' }}</div><div class="muted">{{ $invoice->client?->address }}<br>{{ $invoice->client?->zip }} {{ $invoice->client?->city }}</div></td><td><div class="cyan">IZVRŠAVANJE</div><div class="muted">rok: <strong>{{ $invoice->due_date?->format('d.m.Y.') ?? '—' }}</strong><br>plaćanje: <strong>{{ $invoice->payment_type?->label() ?? '—' }}</strong><br>valuta: <strong>{{ $invoice->currency }}</strong></div></td></tr></table><table class="items"><thead><tr><th style="width:5%">#</th><th style="width:43%">STAVKA</th><th class="ct" style="width:8%">JM</th><th class="r" style="width:8%">KOL.</th><th class="r" style="width:14%">CIJENA</th>@if($vat)<th class="r" style="width:8%">PDV</th>@endif<th class="r" style="width:{{ $vat ? '14' : '22' }}%">IZNOS</th></tr></thead><tbody>@foreach($invoice->items as $i=>$item) @php($q=max(1,(int)$item->quantity))<tr><td class="ct">{{ $i+1 }}</td><td><strong>{{ $item->name }}</strong>@if($item->description)<div class="muted">{{ $item->description }}</div>@endif</td><td class="ct">{{ $item->unit?->value }}</td><td class="r">{{ $item->quantity }}</td><td class="r">{{ $f((int)round($item->total/$q)) }} {{ $c }}</td>@if($vat)<td class="r">{{ number_format($item->tax_rate/100,2,',','.') }}%</td>@endif<td class="r"><strong>{{ $f($item->total) }} {{ $c }}</strong></td></tr>@endforeach</tbody></table><table class="sum"><tr><td>osnovica</td><td>{{ $f($invoice->subtotal) }} {{ $c }}</td></tr>@if($vat)<tr><td>pdv</td><td>{{ $f($invoice->tax_total) }} {{ $c }}</td></tr>@endif<tr class="total"><td>UKUPNO</td><td>{{ $f($invoice->total) }} {{ $c }}</td></tr></table>@if($invoice->notes)<div class="box"><span class="cyan">NAPOMENA</span><br>{{ $invoice->notes }}</div>@endif<div class="box"><span class="cyan">PLAĆANJE</span><br>@forelse($bankAccounts as $a)<strong>{{ $a->bank_name }}</strong> · {{ $a->account_number }}<br>@empty<span class="muted">Podaci za bankovni račun nisu uneseni.</span>@endfor